1	import { z } from "zod";
2	
3	/**
4	 * A rules preset (§18). The slice deliberately runs with fewer rubbing types, rubbings and islands than the alpha;
5	 * keeping the difference in data means slice shortcuts cannot silently ship into the main mode.
6	 */
7	export const rulesPresetSchema = z
8	  .strictObject({
9	    id: z.enum(["slice", "alpha"]),
10	    maxPlayers: z.int().min(1).max(8),
11	    rubbingTypes: z.int().positive(),
12	    rubbings: z.int().positive(),
13	    islands: z.int().positive(),
14	    sourcesPerIsland: z.int().positive(),
15	    fruitKits: z.int().positive(),
16	  })
17	  .superRefine((preset, ctx) => {
18	    if (preset.rubbings !== preset.islands * preset.sourcesPerIsland) {
19	      ctx.addIssue({
20	        code: "custom",
21	        path: ["rubbings"],
22	        message: `rubbings (${preset.rubbings}) must equal islands × sourcesPerIsland (${preset.islands * preset.sourcesPerIsland})`,
23	      });
24	    }
25	    if (preset.rubbings % preset.rubbingTypes !== 0) {
26	      ctx.addIssue({
27	        code: "custom",
28	        path: ["rubbingTypes"],
29	        message: `rubbings (${preset.rubbings}) must split evenly across ${preset.rubbingTypes} types`,
30	      });
31	    }
32	  });
33	
34	export type RulesPreset = z.infer<typeof rulesPresetSchema>;
35	export type RulesPresetId = RulesPreset["id"];
36	
37	export const rulesPresets = {
38	  /** Stage 2: four private players, four small islands with two sources each, two rubbing types, two fruits. */
39	  slice: { id: "slice", maxPlayers: 4, rubbingTypes: 2, rubbings: 8, islands: 4, sourcesPerIsland: 2, fruitKits: 2 },
40	  /** Stage 3: eight players, 12 islands with one source each, four rubbing types, six fruits. */
41	  alpha: { id: "alpha", maxPlayers: 8, rubbingTypes: 4, rubbings: 12, islands: 12, sourcesPerIsland: 1, fruitKits: 6 },
42	} as const satisfies Record<RulesPresetId, RulesPreset>;
43	
44	export type ValidationResult<T> = { ok: true; value: T } | { ok: false; issues: string[] };
45	
46	export function formatIssues(error: z.ZodError): string[] {
47	  return error.issues.map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`);
48	}
49	
50	export function validateRulesPreset(candidate: unknown): ValidationResult<RulesPreset> {
51	  const parsed = rulesPresetSchema.safeParse(candidate);
52	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
